#!/usr/bin/env bash
# ft-merge-land.sh <PR번호> --approve-sha <40hex> [--repo <dir>] [--remote origin] [--target main]   (R230 교정 2 H1 · 오빠 판정 1875 «로컬 착지 강제»)
#   main 병합 = 이 도구뿐(gh pr merge·ft-gh-as-tank.sh pr merge 는 훅이 막는다). 검사한 트리 == 실제로 main 에 놓이는 트리 — 틈은 git 서버의 non-FF 거절이 닫는다.
#   ① 오빠 승인 값(--approve-sha = 승인한 PR head sha · 없으면 실행 0 · 지금 head 가 다르면 «A 뒤 main 병합만 + 자기 변경 동일» 일 때만 ft-approval-equiv 로 통과 — R247 판정 1917) ② PR OPEN·base main·head sha 결속 ③ PR head fetch(pull/N/head → 개인 ref refs/ft-land/N · r706 · r1127: pull ref 없음 ∧ 같은 리포 PR 이면 가지 headRefName 를 같은 ref 로 받아 headRefOid 대조 · INFO 1줄) ④ ft-merge-gate(main 포함·줄 계약)
#   ⑤ Q = commit-tree <S^{tree}> -p <M>(squash 1커밋 · 메시지 = PR 제목·본문 + PR #N) · --ff(R392) = 승인 sha == PR head ∧ main 이 head 의 조상일 때만 Q=S(commit-tree 0 · 전송 객체 0 · 커밋 수 보존) ⑥ git push origin Q:refs/heads/main (force 0 · non-FF = 착지 0)
#   ⑦ PR 에 착지 sha 코멘트 + 닫기. 7초 룰: gh 7 s + 재시도 1, fetch 는 r1363 기본 25 s(판정 4114) + 재시도 1 · push 는 크기 비례 PB=min(F + 7 s × ceil(객체수/U0), 70 s)(fm_push_bound · R354) · 실제 상한 AB=min(PB, 남은 시간)(남은 11 s·PB 70 이면 11 s 한 번 · timeout 이면 재시도 0) · 재시도 1 은 «서버 응답 전 연결 실패» 뿐(timeout·reset·remote 출력 = 불명 → ls-remote 1회로 착지됨/착지 0/불명 판정) · ★r1336: 1차가 timeout(rc124/143)이고 ls-remote 가 «원격 main = 착지 부모 M»(착지 0 확정)이며 남은 ≥ PB 면 재시도 1회(상한 min(2×PB, 남은 시간)) · F 기본 7 · 시도마다 state/push-timing.tsv 1줄(FT_PUSH_TIMING_FILE)★ · 총 마감 70 s. ★r1069 — PR head fetch 상한만 FT_FETCH_TIMEOUT_SEC(1~70 · 오빠 예외 판정)로 늘릴 수 있다: 그 실행은 stdout 첫 줄에 «오빠 예외 판정[ <N>] · 지정 <초>»(N = FT_FETCH_EXCEPTION_ID) · 1회 상한 = min(지정, 남은 시간) · 재시도는 남은 ≥ 지정일 때만 · ★값을 안 주면 «r1363 · 판정 4114» 기본 상한 = 25 s · 착지 1회 마감(FT_LAND_DEADLINE) 안에서만 시도 · push 상한 = min(PB, 남은) r1336 그대로 · ls-remote = min(7, 남은) · 남은 < 1 초 = ls-remote 0 «원격 상태 불명(총 마감)»★★
#   ★모든 모드(ON·OFF·tamper·상태 못 읽음)에서 승인 파일(autonomy-merge-approved/<sha> + autonomy.log 한 줄)이 필요★(R336 · autonomy-merge-guard 와 같은 결속). 승인 파일 폴더 = ft-autonomy.sh state-dir(R253). 성공 줄에 approve-file=<승인 epoch>.
#   exit 0 = 착지+정리 · 1 = REJECT(착지 0) · 2 = usage·승인 없음 · 3 = 착지 성공 · PR 코멘트/닫기 실패(수동) · 6 = 원격 거절(push 출력 «! [remote rejected]» · 착지 0 · 재시도 판단 사람·planner · r2007). FT_GH/FT_GH_WRITE = 시험 주입. ★r2355 K1·K2: push 앞의 시간 상한 단계(닫기 재시도·gh pr view·PR head fetch·게이트·overlap·equiv·press 증거 검사)의 상한 = min(자기 상한, 남은 시간 − push 1단위 PV = F+7) · 남은 − PV < 1 = 그 단계 시작 0 → REJECT «push 몫 예약: <단계> 앞 남은 <s>s − push 1단위 <PV>s < 1 (착지 0 · 다음 틱)»(닫기 재시도만 SKIP + WARN 1줄 · lint 2개는 로컬이라 상한 0 = K2 칸으로만) · 실행이 끝나면(성공·REJECT·exit 2·3·6·--dry) stdout 과 state/land-phase.tsv 에 «LAND-PHASE pr= close= view= fetch= gate= overlap= equiv= press= lint= push= etc= total= left=» 1줄(안 간 단계 «-» · lr_trap 사슬에 1곳 · 쓰기 실패 = WARN · rc 불변).
set -uo pipefail
HERE="$(cd -- "$(dirname -- "${BASH_SOURCE[0]:-$0}")" && pwd)"; [ "${FT_CRITICAL_IN:-}" = "$PPID" ] || [ "${FT_CRITICAL_OFF:-0}" = 1 ] || [[ " $* " == *" --dry "* ]] || [ ! -f "$HERE/ft-critical-notify.sh" ] || exec bash "$HERE/ft-critical-notify.sh" --wrap ft-merge-land "${BASH_SOURCE[0]:-$0}" "$@"   # r1718 A4·A7: 자기 감싸기 1곳 — 본 작업은 자식 1회 · 출력·rc 그대로 · rc 1(REJECT «착지 0») = desk [크리티컬] 1통 · rc 0 = 해결 · rc 2 = 발신 0 (r1718-mut:landcall) · r1986: --dry = 감싸기 0(알림·해결 기록 0)
. "$HERE/ft-merge-lib.sh"; . "$HERE/ft-evidence-lib.sh" && [ -n "${FT_EVIDENCE_RX:-}" ] || { echo "REJECT 증거 로그 판정식 없음($HERE/ft-evidence-lib.sh) — 실행 0"; exit 2; }; [ -f "$HERE/ft-heavy-slot-lib.sh" ] || { echo "REJECT ft-heavy-slot-lib.sh 없음: $HERE — 실행 0"; exit 2; }; . "$HERE/ft-heavy-slot-lib.sh"   # r449: 증거 판정식(pre-commit·ft-evidence-untrack 과 같은 함수) · r1286: 무거운 git 전역 자리(동시 2) — 없으면 조용한 통과 0
PR=""; AP=""; REPO=""; REMOTE="origin"; TARGET="main"; FF=""; S0=""; CAM=""; AMK=""; T0=$SECONDS; ROK=""; ROKA=(); DRY=""; LTCL=0; LTCD=0; LTIN=0; LTNO=0; LTSH=0; LTLG=0; LTK=""; LTH=0; SC=""; SV=""; SF=""; SG=""; SO=""; SE=""; SL=""; SP=""; PCUR=""; PCS=0; SPE=""; RU="$(fm_push_calc '?' 2>/dev/null)"
GH_R="${FT_GH:-gh}"; GH_W="${FT_GH_WRITE:-$HERE/ft-gh-as-tank.sh}"
usage() { echo "usage: $0 <PR번호> --approve-sha <40hex> [--ff] [--repo <dir>] [--remote origin] [--target main] [--replace-ok <경로>@<sha>#§<절>] [--dry]" >&2; exit 2; }
while [ $# -gt 0 ]; do case "$1" in
  --approve-sha) [ $# -ge 2 ] || usage; AP="$2"; shift 2;; --replace-ok) [ $# -ge 2 ] || usage; ROK="$2"; ROKA=(--replace-ok "$2"); shift 2;;   # r1741: DA 판정문 replace-ok = 게이트로 그대로
  --ff) FF=1; shift;; --dry) DRY=1; shift;;   # r1986: 착지와 같은 판정(①②③⑤ 자동 병합 C → 게이트 → equiv·비쓰기 검사)만 · push·PR 코멘트/닫기·승인 파일·장부·알림 0 · stdout «DRY ALLOW|DENY <사유>» · rc 0/1/2
  --repo) [ $# -ge 2 ] || usage; REPO="$2"; shift 2;;
  --remote) [ $# -ge 2 ] || usage; REMOTE="$2"; shift 2;;
  --target) [ $# -ge 2 ] || usage; TARGET="$2"; shift 2;;
  -*) usage;; *) [ -z "$PR" ] || usage; PR="$1"; shift;; esac; done
printf '%s' "$PR" | grep -Eq '^[0-9]+$' || usage; trap 'ph_line' EXIT   # r2355 K2: 실행이 끝날 때(성공·REJECT·rc 2·3·6·--dry) «LAND-PHASE» 1줄 — lr_trap 이 이 줄을 lr_exit 뒤에 이어 붙인다(임시 파일 지우기 덮어쓰기 0)
[ -z "$AP" ] || printf '%s' "$AP" | grep -Eq '^[0-9a-f]{40}$' || { echo "REJECT 오빠 병합 승인 값(--approve-sha <PR head 40hex>) 없음 — 실행 0"; exit 2; }; [ -z "$DRY" ] || [ -n "$AP" ] || usage   # r1986: dry 는 승인 sha 필수(문서 면제 길은 autonomy.log 에 쓴다) · R725: 빈 값 = 문서 전용 판정 경로(아래 ft_doc_exempt.py)
[ -n "$REPO" ] || REPO="$(git rev-parse --show-toplevel 2>/dev/null)" || { echo "REJECT repo 를 찾을 수 없음"; exit 1; }
G() { git -C "$REPO" "$@"; }; lr_del() { local e; e="$(G update-ref -d "refs/ft-land/$PR" ${1:+"$1"} 2>&1)" || { echo "WARN 개인 ref 정리 실패 refs/ft-land/$PR — ${e:-git 원문 0}" >&2; return 1; }; }   # r706: 개인 ref 정리 = 이 도구 하나 책임(공용 FETCH_HEAD 는 다른 좌석 fetch 가 덮는다)
rej() { [ -z "$DRY" ] || { echo "DRY DENY $*"; exit 1; }; echo "REJECT $* (착지 0)"; exit 1; }
CTX="$(fm_land_ctx "$REPO" "$REMOTE" "${FT_ROOT:-}" "$TARGET")" || rej "대상 리포 remote URL 해석 실패(fetch·push URL 이 같은 github owner/name 이어야) — 어느 리포 PR 인지 몰라 착지 0"   # r1687: 기준 헤드는 대상 가지마다 따로(base-head@ops-main-base) · r648: 승인 루트 ≠ 대상 리포   # r648: 승인 루트(BYZ) ≠ 대상 리포
IFS='|' read -r ROOT CROSS SLUG BH RROOT <<<"$CTX"; STATE="${FT_AUTONOMY_STATE_DIR:-$ROOT/.fable-team/state}"
pushsave() { local f; mkdir -p -- "$STATE/push-out" 2>/dev/null && f="$STATE/push-out/push-$PR-$(date +%Y%m%dT%H%M%S)-$$.log" && printf '%s\n' "$POUT" >"$f" 2>/dev/null && printf '%s' "$f"; }   # r595: push 출력 전문을 상태 폴더에 남긴다 — 경로 출력, 쓰기 실패면 rc≠0(삼키기 0)
pushwhy() { local f; f="$(pushsave)" || f=""; printf '사유 %s · 마지막 줄 %s · 전문=%s' "$(printf '%s\n' "$POUT" | grep -E '^(remote:|PUSH_DENIED|! \[)' | head -n 3 | cut -c1-200 | tr '\n' '|' | sed 's/|$//;s/|/ · /g')" "$(printf '%s' "$POUT" | tail -n1)" "${f:-저장 실패}"; }   # r595: 거부 사유 줄(앞 3개) + 마지막 줄 + 전문 파일 경로
LIM="${FT_LAND_TOTAL_S:-67}"; { [ "$LIM" -le 100 ] && [ "$LIM" -ge 1 ]; } 2>/dev/null || LIM=100; fm_fetch_sec >/dev/null; FTS="$FM_FETCH_SEC"; fm_fetch_banner; [ -n "${FT_LAND_DEADLINE:-}" ] || { FT_LAND_DEADLINE=$(( $(date +%s) + LIM )); export FT_LAND_DEADLINE; }   # 총 마감 — 시험 주입은 줄이기만 가능(100 s 초과 불가 · 판정 4114 = 25초 × 단계 4) · r1069: FTS = fetch 상한(지정이면 첫 줄 «오빠 예외 판정») · r1363: 착지 1회 마감(FT_LAND_DEADLINE epoch 초 · 시험 주입값은 덮지 않는다)을 export 해 자식 ft-merge-gate·fm_fetch 가 같은 마감을 넘지 않게 한다 · «INFO fetch 상한 <초>(F=<f>)» 1줄은 lr_exit(맨 끝)에서 쓴다(LANDED 접두 계약 보존)
land_left() { local a=$((LIM - (SECONDS - T0))) b=$((FT_LAND_DEADLINE - $(date +%s))); printf '%s' "$((a < b ? a : b))"; }; deadline() { [ "$(land_left)" -gt 0 ] || rej "총 마감 $LIM s 초과"; }; ltk() { LTH=1; LTK="${LTK:+$LTK,}$1"; }; lt_line() { [ "$LTH" = 1 ] || return 0; echo "LAND-TAIL close=$LTCL card=$LTCD install=$LTIN notify=$LTNO shim=$LTSH lag=$LTLG left=$(land_left) skip=$LTK"; }; rsv() { deadline; local b; b=$(( $(land_left) - RU )); RSV=""; [ "$b" -ge 1 ] 2>/dev/null || return 1; [ "$b" -lt "$2" ] && RSV="$b" || RSV="$2"; return 0; }; rv() { local s="$1" rc=0 i b; shift; for i in 1 2; do rsv _ "$s" || { [ "$i" = 1 ] && return 125; break; }; b="$RSV"; fm_try "$b" "$@" && return 0; rc=$?; done; return "$rc"; }; fbf() { local b rc=0 i; for i in 1 2; do rsv _ "$FTS" || { [ "$i" = 1 ] && return 125; break; }; b="$RSV"; fm_try "$b" git -c gc.auto=0 -C "$REPO" fetch --quiet "$REMOTE" "$1" && return 0; rc=$?; done; return "$rc"; }; phs() { case "${PCUR:-}" in ""|-) ;; close) SC=$(( ${SC:-0} + SECONDS - PCS ));; view) SV=$(( ${SV:-0} + SECONDS - PCS ));; fetch) SF=$(( ${SF:-0} + SECONDS - PCS ));; gate) SG=$(( ${SG:-0} + SECONDS - PCS ));; overlap) SO=$(( ${SO:-0} + SECONDS - PCS ));; equiv) SE=$(( ${SE:-0} + SECONDS - PCS ));; press) SPE=$(( ${SPE:-0} + SECONDS - PCS ));; lint) SL=$(( ${SL:-0} + SECONDS - PCS ));; push) SP=$(( ${SP:-0} + SECONDS - PCS ));; esac; PCUR="${1:-}"; PCS=$SECONDS; }; ph_line() { phs -; local t s su=0 lc; t=$((SECONDS - T0)); for s in "${SC:-0}" "${SV:-0}" "${SF:-0}" "${SG:-0}" "${SO:-0}" "${SE:-0}" "${SPE:-0}" "${SL:-0}" "${SP:-0}"; do su=$((su + s)); done; lc="$( { [ -n "${LIM:-}" ] && land_left; } 2>/dev/null || printf '?')"; s="$(printf 'pr=%s close=%s view=%s fetch=%s gate=%s overlap=%s equiv=%s press=%s lint=%s push=%s etc=%s total=%s left=%s' "$PR" "${SC:--}" "${SV:--}" "${SF:--}" "${SG:--}" "${SO:--}" "${SE:--}" "${SPE:--}" "${SL:--}" "${SP:--}" "$((t - su))" "$t" "$lc")"; echo "LAND-PHASE $s"; { [ -z "${STATE:-}" ] || { mkdir -p "$STATE" 2>/dev/null && printf '%s %s\n' "$(date +%Y-%m-%dT%H:%M:%S)" "$s" >>"$STATE/land-phase.tsv"; }; } 2>/dev/null || echo "WARN land-phase 기록 실패(${STATE:-?}/land-phase.tsv) — 착지 rc 불변" >&2; };   # r2355 K1·K2: rsv = 이번 단계 상한(min(자기 상한, 남은 − PV)) · rc1 = 예약 없음 · rv/fbf = 재시도 1회도 같은 예약 안(rc125 = 시작 0) · phs = 단계 초 한 곳(PCUR) · ph_line = LAND-PHASE 1줄 + tsv   # r2320 T1·T3: 남은 초 한 시계 = min(LIM − 지난 초, FT_LAND_DEADLINE − 지금) — deadline()·push REM·ls-remote 상한·재시도 문턱이 «같은 함수»(DA ⓐ · env 마감이 먼저면 그 자리에서 깨끗한 REJECT 1줄) · 꼬리 단계 하나라도 호출 0·rc124/143 이면 맨 끝 «LAND-TAIL close= card= install= notify= shim= lag= left= skip=» 1줄(모두 정상 = 0줄)
AUT="$HERE/ft-autonomy.sh"   # R336: 모든 모드(on·off·tamper·불명)에서 오빠 승인 파일 + log 한 줄 필요 — OFF 에서 master 가 sha 만 적어 착지하던 틈을 닫는다
APR="$(fm_live_root "${FT_ROOT:-}")"; APRC=$?; AST=""; [ "$APRC" != 0 ] || AST="$(FT_ROOT="$APR" bash "$AUT" state-dir 2>/dev/null)"; [ "$APRC" != 1 ] || AST="$(bash "$AUT" state-dir 2>/dev/null)"   # r1746 A6: 승인 폴더 = 승인 루트(fm_live_root — 게이트 replace-ok 판정문 리포와 같은 함수) · FT_ROOT=BYZ 메인 루트여도 LIVE_ROOT 의 state · LIVE_ROOT 못 읽음(rc2) = 해석 실패 · 승인 루트 못 정함(rc1)만 옛 길   # r648: 승인 폴더 = 이 정식 리졸버 하나뿐(공용 루트를 직접 쓰는 길 0)
[ "$APRC" != 1 ] || [ -n "$AST" ] || AST="$(cd "${FT_ROOT:-$ROOT}" 2>/dev/null && bash "$AUT" state-dir 2>/dev/null)"   # 팩 cwd 등에서 해석 실패할 때만 부른 리포 안에서 재시도(LIVE_ROOT 그대로 작동)
[ -n "$AST" ] || { echo "REJECT 자율 상태 폴더 해석 실패 — 실행 0"; exit 2; }
[ -z "$AP" ] || { AF="$AST/autonomy-merge-approved/$AP"   # R725: 승인 값을 준 경우만 승인 파일을 본다(빈 값 = doc-exempt 판정이 가른다)
[ "$(wc -l < "$AF" 2>/dev/null | tr -d ' ')" = 1 ] && grep -q "^approve-merge $AP " "$AF" && grep -qxF "$(head -n1 "$AF")" "$AST/autonomy.log" 2>/dev/null \
  || { [ -z "$DRY" ] || rej "오빠 승인 파일 없음(approve-merge $AP 승인 파일·로그 한 줄) — dry 는 기다림 표식 0"; fm_ap_wait "$REPO" "$REMOTE" "$TARGET" "$AP" "$AST"; exit 2; }   # r1117: 거절 sha 기다림 표식 → approve-merge 가 그 좌석에 [승인 도착] 1통 · r1200: 커밋 아님·승인된 조상 있음 = 표식 0(ft-merge-lib.sh)
AFE="$(awk '{print $4}' "$AF")"; AFV="$(awk '{print $3}' "$AF")"; ATF="$AST/autonomy-merge-target/$AP"; if [ -e "$ATF" ]; then ATG="$(head -n1 "$ATF" 2>/dev/null)"; elif grep -qE "^(scope-use S[0-9]+|standing-use D[12]) $AP " "$AST/autonomy.log" 2>/dev/null; then ATG=main; else ATG="$TARGET"; fi; [ "$ATG" = "$TARGET" ] || rej "승인 base ${ATG:-읽기 실패} ≠ 착지 base $TARGET — 그 base 로 다시 분류 필요"; }   # r1955 마①: 승인 base 결속(autonomy-merge-target/<sha> · 없음 + 분류 승인(scope-use·standing-use 줄) = main = 이 카드 전 승인 · 없음 + 오빠 손 approve-merge 만 = 분류 없음 → 결속 0)   # 승인 epoch — merge-gate.log 에 «누가 언제 승인했나» 를 남긴다
CPL="$AST/merge-close-pending.jsonl"; CPK="${SLUG:-$RROOT}"; CRS=$(( $(land_left) - RU )); if [ "$CRS" -ge 7 ]; then [ -n "$DRY" ] || { phs close; fm_close_retry "$CPL" "$CPK" "$SLUG" "$GH_W" "$CRS"; phs; }; else echo "WARN 닫기 재시도 건너뜀 — push 몫 예약(남은 $(land_left)s − push 1단위 ${RU}s < 7s) · 본 PR 계속"; fi   # r2355 K1: 상한 = min(7, 남은 − PV) · 예약이 모자라면(< 7) 건너뜀 = REJECT 아님(반례 ③)   # r1131: ⑦ 실패로 «닫기 대기» 장부에 남은 같은 리포 PR(최대 3)을 먼저 다시 닫는다 — 남은 ≥ 20 s 일 때만 · 성공 = 장부에서 지움 · 착지 판정·rc 영향 0
rsv view 7 || rej "push 몫 예약: gh pr view 앞 남은 $(land_left)s − push 1단위 ${RU}s < 1 (착지 0 · 다음 틱)"; VS="$RSV"; phs view; JSON="$(rv "$VS" "$GH_R" pr view "$PR" ${SLUG:+-R "$SLUG"} --json headRefOid,headRefName,isCrossRepository,title,body,state,baseRefName)"; VX=$?; phs; [ "$VX" != 125 ] || rej "push 몫 예약: gh pr view 앞 남은 $(land_left)s − push 1단위 ${RU}s < 1 (착지 0 · 다음 틱)"; [ "$VX" = 0 ] || rej "gh pr view $PR 실패(7 s + 재시도 1)"; deadline
pf() { printf '%s' "$JSON" | python3 -c 'import json,sys;print(json.load(sys.stdin).get(sys.argv[1]) or "")' "$1"; }
[ "$(pf state)" = OPEN ] || rej "PR #$PR 가 OPEN 아님($(pf state))"; [ "$(pf baseRefName)" = "$TARGET" ] || rej "PR #$PR base 가 $TARGET 아님($(pf baseRefName))"
